<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import api from'../../services/api';import type{PageResult}from'../../types/medical'
const route=useRoute(),router=useRouter(),rows=ref<any[]>([]),loading=ref(false),keyword=ref(''),total=ref(0),page=ref(1),detail=ref<any>(null),drawer=ref(false),department=ref(''),departments=ref<any[]>([])
const isDoctors=computed(()=>['admin-doctors','patient-doctors'].includes(String(route.name))),isPatientSearch=computed(()=>route.name==='patient-doctors')
const title=computed(()=>isDoctors.value?(isPatientSearch.value?'医师查询':'医师管理'):route.name==='doctor-patients'?'我的患者':'患者管理')
const description=computed(()=>isPatientSearch.value?'按科室与专长查找医师，直接进入预约挂号':'搜索、查看档案与当前业务状态')
async function load(){loading.value=true;try{const endpoint=isDoctors.value?'doctors/':'patients/';const{data}=await api.get<any[]|PageResult<any>>(endpoint,{params:{page:page.value,search:keyword.value,department:department.value||undefined}});rows.value=Array.isArray(data)?data:data.results;total.value=Array.isArray(data)?data.length:data.count}catch{rows.value=[];total.value=0}finally{loading.value=false}}
function view(row:any){detail.value=row;drawer.value=true}
function book(row:any){router.push({path:'/patient/appointments',query:{department:row.department_id,doctor:row.id}})}
watch([page,department],load);watch(()=>route.name,()=>{page.value=1;keyword.value='';load()});onMounted(async()=>{try{const{data}=await api.get('departments/',{params:{status:'active'}});departments.value=Array.isArray(data)?data:data.results}catch{}await load()})
</script>
<template><section><div class="page-heading"><div><h1>{{title}}</h1><p>{{description}}</p></div></div><el-card class="table-card"><div class="table-tools"><el-input v-model="keyword" clearable placeholder="搜索姓名、编号或专业方向" @keyup.enter="load"/><el-select v-if="isDoctors" v-model="department" clearable placeholder="全部科室" style="width:190px"><el-option v-for="item in departments" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-button @click="load">查询</el-button></div><el-table v-loading="loading" :data="rows" empty-text="暂无匹配资料"><template v-if="isDoctors"><el-table-column prop="doctor_no" label="医师编号"/><el-table-column prop="full_name" label="姓名"/><el-table-column prop="department_name" label="主科室"/><el-table-column prop="title" label="职称"/><el-table-column prop="specialty" label="专业方向" min-width="220" show-overflow-tooltip/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.is_available?'success':'info'">{{row.is_available?'可接诊':'暂停接诊'}}</el-tag></template></el-table-column></template><template v-else><el-table-column prop="patient_no" label="患者编号"/><el-table-column prop="full_name" label="姓名"/><el-table-column prop="gender_display" label="性别"/><el-table-column prop="birth_date" label="出生日期"/><el-table-column prop="phone" label="手机号"/><el-table-column prop="blood_group" label="血型"/></template><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button link type="primary" @click="view(row)">查看详情</el-button><el-button v-if="isPatientSearch&&row.is_available" link type="success" @click="book(row)">预约</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" layout="prev,pager,next" :total="total"/></div></el-card><el-drawer v-model="drawer" :title="isDoctors?'医师详情':'患者档案'" size="min(520px,94vw)"><el-descriptions v-if="detail" :column="1" border><template v-if="isDoctors"><el-descriptions-item label="姓名">{{detail.full_name}}</el-descriptions-item><el-descriptions-item label="科室">{{detail.department_names?.join('、')||detail.department_name}}</el-descriptions-item><el-descriptions-item label="职称">{{detail.title||'—'}}</el-descriptions-item><el-descriptions-item label="专业方向">{{detail.specialty||'—'}}</el-descriptions-item><el-descriptions-item label="简介">{{detail.introduction||'—'}}</el-descriptions-item></template><template v-else><el-descriptions-item label="姓名">{{detail.full_name}}</el-descriptions-item><el-descriptions-item label="手机号">{{detail.phone||'—'}}</el-descriptions-item><el-descriptions-item label="过敏史">{{detail.allergies||'无已知过敏'}}</el-descriptions-item><el-descriptions-item label="既往病史">{{detail.medical_history||'—'}}</el-descriptions-item><el-descriptions-item label="地址">{{detail.address||'—'}}</el-descriptions-item></template></el-descriptions></el-drawer></section></template>
